import { test, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import * as t from '../todos.js';
beforeEach(() => t.reset());
test('filters', () => {
  t.add('a'); const b = t.add('b'); t.complete(b.id);
  assert.deepEqual(t.list({ done: false }).map((i) => i.title), ['a']);
  assert.deepEqual(t.list({ done: true }).map((i) => i.title), ['b']);
  assert.equal(t.list().length, 2);
});
test('remove', () => {
  const a = t.add('a'); t.add('b');
  assert.equal(t.remove(a.id), true);
  assert.equal(t.remove(a.id), false);
  assert.deepEqual(t.list().map((i) => i.title), ['b']);
});

