let items = [];
let nextId = 1;
export function reset() { items = []; nextId = 1; }
export function add(title) {
  const item = { id: nextId++, title, done: false };
  items.push(item);
  return item;
}
export function complete(id) {
  const item = items.find((i) => i.id === id);
  if (item) item.done = true;
  return Boolean(item);
}
export function list({ done } = {}) {
  return done === undefined ? [...items] : items.filter((i) => i.done === done);
}
export function remove(id) {
  const k = items.findIndex((i) => i.id === id);
  if (k < 0) return false;
  items.splice(k, 1);
  return true;
}
